changeSet.sql:
CREATE VIEW marketplace_estate_fees WITH (security_barrier = true) AS SELECT f.id AS fee_id, f.estate_id AS estate_id, f.fee_type AS fee_type, f.label AS label, f.amount AS amount, f.amount_min AS amount_min, f.amount_max AS amount_max, f.currency AS currency, f.is_fixed AS is_fixed, f.variation_basis AS variation_basis, f.due_trigger AS due_trigger, f.refundable AS refundable, f.is_mandatory AS is_mandatory, f.notes AS notes FROM estate_fees f JOIN estates e ON e.id = f.estate_id JOIN marketplace_estate_eligibility el ON el.estate_id = f.estate_id AND el.eligible -- The current declaration only. estates.fees_version is the -- authoritative pointer: a max(version) subquery would return -- nothing for an estate that declared an empty schedule, which -- is a legitimate state. WHERE f.deleted = false AND f.version = e.fees_version;
CREATE VIEW marketplace_refund_terms WITH (security_barrier = true) AS SELECT DISTINCT ON (r.estate_id) r.estate_id AS estate_id, r.deduction_pct AS deduction_pct, r.processing_days AS processing_days, r.applies_to AS applies_to, r.non_refundable_fee_types AS non_refundable_fee_types, r.notes AS notes FROM estate_refund_terms r JOIN marketplace_estate_eligibility el ON el.estate_id = r.estate_id AND el.eligible WHERE r.deleted = false ORDER BY r.estate_id, r.version DESC;
CREATE VIEW marketplace_default_terms WITH (security_barrier = true) AS SELECT DISTINCT ON (d.estate_id) d.id AS default_terms_id, d.estate_id AS estate_id, d.revocation_trigger AS revocation_trigger, d.revocation_notice_days AS revocation_notice_days, d.on_revocation_refund AS on_revocation_refund, d.development_deadline_months AS development_deadline_months, d.transfer_requires_consent AS transfer_requires_consent, d.notes AS notes FROM estate_default_terms d JOIN marketplace_estate_eligibility el ON el.estate_id = d.estate_id AND el.eligible WHERE d.deleted = false ORDER BY d.estate_id, d.version DESC;
CREATE VIEW marketplace_penalty_tiers WITH (security_barrier = true) AS SELECT t.id AS penalty_tier_id, d.estate_id AS estate_id, t.months_late AS months_late, t.penalty_pct AS penalty_pct FROM estate_default_penalty_tiers t JOIN marketplace_default_terms d ON d.default_terms_id = t.default_terms_id WHERE t.deleted = false;
REVOKE ALL ON marketplace_estate_fees, marketplace_refund_terms, marketplace_default_terms, marketplace_penalty_tiers FROM PUBLIC; REVOKE ALL ON marketplace_estate_fees, marketplace_refund_terms, marketplace_default_terms, marketplace_penalty_tiers FROM ${appDbUsername}; -- SELECT only. Changeset 019's default privileges would otherwise -- grant INSERT/UPDATE/DELETE on every new relation, views -- included, and a write through an owner-privileged view would -- bypass RLS entirely. GRANT SELECT ON marketplace_estate_fees, marketplace_refund_terms, marketplace_default_terms, marketplace_penalty_tiers TO ${appDbUsername};

changeSet.rollback:
DROP VIEW marketplace_penalty_tiers;
DROP VIEW marketplace_default_terms;
DROP VIEW marketplace_refund_terms;
DROP VIEW marketplace_estate_fees;
